+export interface Transport {send(body: string): string;}
+export const deliver = (transport: Transport, body: string): string => transport.send(body);
diff --git a/src/online.ts b/src/online.ts
new file mode 100644
--- /dev/null
+++ b/src/online.ts
@@ -0,0 +1,3 @@
